import {Link, PageHeader, Stack} from '@primer/react'

type NavigationHeaderProps = {
  target: string
  propertyName: string
  listPath: string
}

export const NavigationHeader = ({target, propertyName, listPath}: NavigationHeaderProps) => {
  return (
    <PageHeader>
      <PageHeader.TitleArea>
        <PageHeader.Title>
          <Stack direction="horizontal" gap="condensed">
            <Link href={listPath}>{target} Custom Properties</Link> <span>/</span>
            <span>{propertyName}</span>
          </Stack>
        </PageHeader.Title>
      </PageHeader.TitleArea>
    </PageHeader>
  )
}

try{ NavigationHeader.displayName ||= 'NavigationHeader' } catch {}