import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {Blankslate} from '@primer/react/experimental'
import {ValuesTable} from '@github-ui/stafftools-custom-properties-core/values/table'
import {useParams} from '@github-ui/react-router'
import {orgCustomPropertyDefinitionStafftoolsDetailsPath} from '../paths'

export function RepositoryCustomPropertyValuesIndexPage() {
  const {properties} = useRoutePayload<{properties: Record<string, string>}>()
  const {owner} = useParams()

  const tableData = Object.entries(properties).map(([key, value]) => ({
    id: key,
    property: key,
    value,
  }))

  if (tableData.length === 0) {
    return (
      <Blankslate border>
        <Blankslate.Heading>No properties set in this repository</Blankslate.Heading>
      </Blankslate>
    )
  }

  return (
    <ValuesTable
      data={tableData}
      source={owner || ''}
      getDefinitionDetailsPath={orgCustomPropertyDefinitionStafftoolsDetailsPath}
    />
  )
}

try{ RepositoryCustomPropertyValuesIndexPage.displayName ||= 'RepositoryCustomPropertyValuesIndexPage' } catch {}