type DefinitionTextFieldProps = {
  label: string
  value: string | null
}

export const DefinitionTextField = ({label, value}: DefinitionTextFieldProps) => {
  if (value === null) return null

  return (
    <span>
      <strong>{label}:</strong> {value}
    </span>
  )
}

try{ DefinitionTextField.displayName ||= 'DefinitionTextField' } catch {}